using System;
using System.IO;
using System.Linq;
using Touchfish;
public static partial class RuleTests {
 static bool BadSecretView(LanState view){try{LanProtocol.ReadView(catalog,view);return false;}catch(InvalidDataException){return true;}}
 static void SecretOwner(){
  var g=Game();g.ArmSecret(0,new HandCard{Id=id++,CardId="VAN_EX1_287"});g.ArmSecret(1,new HandCard{Id=id++,CardId="VAN_EX1_289"});
  for(int seat=0;seat<2;seat++){var view=LanProtocol.View(g,seat,"own",1);string own=seat==0?"VAN_EX1_287":"VAN_EX1_289",enemy=seat==0?"VAN_EX1_289":"VAN_EX1_287";Check(view.ViewerSeat==seat&&view.OwnSecrets.SequenceEqual(new[]{own}),"Only recipient's own active secret identities exported");string wire=JsonData.Serializer().Serialize(view);Check(wire.Contains(own)&&!wire.Contains(enemy),"Opponent secret identity never enters serialized snapshot");var copy=LanProtocol.ReadView(catalog,LanProtocol.Copy(view));Check(copy.SecretCards(seat).SequenceEqual(new[]{own})&&copy.SecretCards(1-seat).Length==0,"ReadView restores only owner's secret details");Check(copy.Players[0].SecretCount==1&&copy.Players[1].SecretCount==1,"Public counts unchanged by private details");}
  var ids=g.SecretCards(0);ids[0]="VAN_EX1_295";Check(g.SecretCards(0).Single()=="VAN_EX1_287","Tooltip query cannot mutate authoritative secrets");
  var previous=LanProtocol.ReadView(catalog,LanProtocol.View(g,0,"own",1));g.DestroySecrets(0);var next=LanProtocol.ReadView(catalog,LanProtocol.View(g,0,"own",2),previous);Check(next.SecretCards(0).Length==0&&next.Players[0].SecretCount==0,"Destroyed secrets do not linger in refreshed owner view");
  g=Game();g.ArmSecret(0,new HandCard{Id=id++,CardId="VAN_EX1_287"});g.EndTurn();Check(g.Play(1,Hand(g,"CS2_029",1),new MatchTarget(0)).Success,"Counterspell fixture resolves");var revealed=LanProtocol.View(g,0,"reveal",2);Check(revealed.OwnSecrets.Length==0&&revealed.Log.Any(l=>l.Contains("奥秘触发：法术反制")),"Triggered secret leaves hover list and becomes public normally");
  g=Game();foreach(var p in g.Players){p.Deck.Clear();p.Hand.Clear();}g.Players[0].Deck.Add("VAN_EX1_287");g.Players[1].Deck.Add("VAN_EX1_289");var a=g.Summon(0,"FP1_004");var b=g.Summon(1,"FP1_004");a.DamageTaken=a.MaxHealth;b.DamageTaken=b.MaxHealth;g.Cleanup();Check(g.VisualEvents.Count(e=>e.Kind=="secret-armed")==2,"Each successful Scientist deathrattle emits an owner notice");
  for(int seat=0;seat<2;seat++){var view=LanProtocol.View(g,seat,"scientists",1);var notices=view.VisualEvents.Where(e=>e.Kind=="secret-armed").ToArray();Check(notices.Length==1&&notices[0].RecipientSeat==seat&&notices[0].Seat==seat,"Each side receives only its own Scientist notice");Check(notices[0].CardId==view.OwnSecrets.Single(),"Notice names the actual selected secret");Check(!view.Log.Any(l=>l.Contains("法术反制")||l.Contains("寒冰护体")),"Shared log keeps both secret names hidden");Check(view.VisualEvents.All(e=>e.RecipientSeat<0||e.RecipientSeat==seat),"All private events filtered before serialization");var remote=LanProtocol.ReadView(catalog,LanProtocol.Copy(view));Check(remote.VisualEvents.Count(e=>e.Kind=="secret-armed")==1,"Owner notice survives wire roundtrip");var cursor=new MatchVisualCursor();Check(cursor.Take(remote.VisualSession,remote.VisualEvents,true).Count(e=>e.Kind=="secret-armed")==1&&cursor.Take(remote.VisualSession,remote.VisualEvents,true).Length==0,"Repeated snapshots cannot replay Scientist notice");}
  var invalid=LanProtocol.Copy(LanProtocol.View(g,0,"bad",1));invalid.VisualEvents.Single(e=>e.Kind=="secret-armed").RecipientSeat=1;Check(BadSecretView(invalid),"Wrong-recipient private notice rejected");invalid=LanProtocol.Copy(LanProtocol.View(g,0,"bad",1));invalid.OwnSecrets=new[]{"VAN_CS2_029"};Check(BadSecretView(invalid),"Non-secret identity rejected");invalid=LanProtocol.Copy(LanProtocol.View(g,0,"bad",1));invalid.ViewerSeat=-1;Check(BadSecretView(invalid),"Missing recipient rejected");
  g.VisualEvents.Single(e=>e.Kind=="secret-armed"&&e.Seat==0).RecipientSeat=-1;Check(LanProtocol.View(g,1,"defensive",1).VisualEvents.Where(e=>e.Kind=="secret-armed").All(e=>e.Seat==1),"Secret notice cannot become public when recipient flag is missing");
  g=Game();g.Players[0].Deck.Clear();g.Players[0].Deck.Add("VAN_CS2_029");g.PutSecretFromDeck(0);Check(!g.VisualEvents.Any(e=>e.Kind=="secret-armed"),"No eligible secret means no false notice");g.Players[0].Deck.Add("VAN_EX1_287");g.ArmSecret(0,new HandCard{Id=id++,CardId="VAN_EX1_287"});g.PutSecretFromDeck(0);Check(!g.VisualEvents.Any(e=>e.Kind=="secret-armed")&&g.Players[0].Deck.Count==2,"Duplicate secret stays in deck without false notice");
 }
}
